(function(root){'use strict';const providers={youtube:{name:'YouTube / Google',origin:'https://www.google.com',path:'/device',guide:'Open YouTube on your TV, choose Sign in, then choose the option to use your phone.'},twitch:{name:'Twitch',origin:'https://www.twitch.tv',path:'/activate',guide:'Open Twitch, choose Log in, then follow its activate-on-another-device instructions.'}};
function safeURI(provider,value,code){try{const u=new URL(value),p=providers[provider];if(!p||u.username||u.password||u.hash)return false;if(provider==='youtube'){if(!['https://www.google.com/device','https://yt.be/activate'].includes(u.origin+u.pathname))return false}else if(u.origin!==p.origin||u.pathname!==p.path)return false;const entries=[...u.searchParams];if(provider==='youtube')return entries.length===0;return entries.length<=2&&new Set(entries.map(x=>x[0])).size===entries.length&&entries.every(([key,v])=>key==='public'?v==='true':key==='device-code'&&v===code)}catch{return false}}
function create({provider,requestId,navigationId,now=Date.now,monotonic=()=>performance.now()}){if(!providers[provider]||typeof requestId!=='string'||typeof navigationId!=='string')throw Error('INVALID_FLOW');let active=true,deadline=0,state={status:'requesting',provider,userCode:'',verificationUri:'',remaining:0,flowId:null};
function clear(status){active=false;deadline=0;state={status,provider,userCode:'',verificationUri:'',remaining:0,flowId:null}}
return{get state(){return{...state}},accept(packet){if(!active||!packet||typeof packet!=='object'||packet.version!==1||packet.provider!==provider||packet.requestId!==requestId||packet.navigationId!==navigationId||typeof packet.flowId!=='string'||!/^[-A-Za-z0-9_]{1,128}$/.test(packet.flowId))return false;const common=['version','provider','requestId','navigationId','flowId','status'];if(packet.status==='pending'){if(Object.keys(packet).some(k=>![...common,'userCode','verificationUri','expiresAt','intervalSec'].includes(k))||typeof packet.userCode!=='string'||!/^[-A-Z0-9 ]{4,32}$/.test(packet.userCode)||!safeURI(provider,packet.verificationUri,packet.userCode)||!Number.isFinite(packet.expiresAt)||packet.expiresAt<=now()||packet.expiresAt-now()>1800000||!Number.isInteger(packet.intervalSec)||packet.intervalSec<1||packet.intervalSec>300||(state.flowId&&state.flowId!==packet.flowId))return false;if(state.status==='pending')return packet.userCode===state.userCode;const duration=packet.expiresAt-now();deadline=monotonic()+duration;state={status:'pending',provider,userCode:packet.userCode,verificationUri:new URL(packet.verificationUri).origin+new URL(packet.verificationUri).pathname,remaining:Math.ceil(duration/1000),flowId:packet.flowId};return true}if(!['approved','denied','expired','error'].includes(packet.status)||Object.keys(packet).some(k=>!common.includes(k))||state.flowId!==packet.flowId)return false;clear(packet.status);return true},tick(){if(state.status==='pending'){state.remaining=Math.max(0,Math.ceil((deadline-monotonic())/1000));if(state.remaining===0)clear('expired')}return{...state}},cancel(){clear('canceled')},dispose(){clear('canceled')}}}
root.OmniDeviceLogin={providers,safeURI,create};
})(window);


